"""POSIX-style word splitting with quoting and no expansions. See task.md."""

from __future__ import annotations


class SplitError(ValueError):
    """Raised for an unterminated quote or a lone trailing backslash."""


def split(line: str) -> list[str]:
    """Split `line` into words. See task.md for the rules."""
    words: list[str] = []
    cur: list[str] = []
    in_word = False
    i = 0
    n = len(line)
    while i < n:
        c = line[i]
        if c == " " or c == "\t":
            if in_word:
                words.append("".join(cur))
                cur = []
                in_word = False
            i += 1
        elif c == "\\":
            if i + 1 >= n:
                raise SplitError("trailing backslash")
            nxt = line[i + 1]
            if nxt != "\n":
                cur.append(nxt)
                in_word = True
            i += 2
        elif c == "'":
            end = line.find("'", i + 1)
            if end < 0:
                raise SplitError("unterminated single quote")
            cur.append(line[i + 1 : end])
            in_word = True
            i = end + 1
        elif c == '"':
            in_word = True
            i += 1
            while True:
                if i >= n:
                    raise SplitError("unterminated double quote")
                d = line[i]
                if d == '"':
                    i += 1
                    break
                if d == "\\" and i + 1 < n:
                    e = line[i + 1]
                    if e == "\n":
                        i += 2
                        continue
                    if e in '$`"\\':
                        cur.append(e)
                        i += 2
                        continue
                cur.append(d)
                i += 1
        elif c == "#" and not in_word:
            break
        else:
            cur.append(c)
            in_word = True
            i += 1
    if in_word:
        words.append("".join(cur))
    return words
